const ITEM_ICON: ReadonlyArray<readonly [RegExp, string]> = [
  [/crossbow/, "crossbow"],
  [/bow\b|longbow|shortbow/, "pocket-bow"],
  [/arrow|bolt|quiver/, "quiver"],
  [/sword|blade|rapier|scimitar|sabre|saber/, "broadsword"],
  [/dagger|knife|dirk/, "plain-dagger"],
  [/axe/, "battle-axe"],
  [/mace|club|hammer|flail|morningstar/, "flanged-mace"],
  [/shield/, "round-shield"],
  [/chain|mail|plate|breastplate|scale/, "chain-mail"],
  [/leather|armou?r|jerkin/, "leather-armor"],
  [/potion|elixir|tonic/, "health-potion"],
  [/ration|bread|food|cheese|meat|jerky/, "sliced-bread"],
  [/key/, "key"],
  [/rope|twine/, "rope-coil"],
  [/torch/, "torch"],
  [/lantern|lamp/, "lantern"],
  [/coin|gold|silver|copper|purse/, "two-coins"],
  [/scroll|parchment/, "scroll-unfurled"],
  [/letter|note|envelope/, "envelope"],
  [/map/, "treasure-map"],
  [/gem|jewel|diamond|ruby|emerald|sapphire/, "cut-diamond"],
  [/ring|amulet|necklace|pendant|locket/, "ring"],
  [/book|tome|journal|diary/, "book-cover"],
  [/flask|vial|bottle|oil|ink/, "round-bottom-flask"],
  [/water|skin\b|waterskin|canteen/, "water-flask"],
  [/herb|leaf|flower|root/, "herbs-bundle"],
  [/cloak|cape|robe/, "cape"],
  [/boot/, "boots"],
  [/pack|bag|sack|satchel/, "knapsack"],
  [/thieves|lockpick|pick/, "lockpicks"],
  [/javelin|spear|lance|trident/, "quiver"]
];

export function iconFor(name: unknown): string {
  const n = String(name ?? "").toLowerCase();
  for (const [re, ic] of ITEM_ICON) {
    if (re.test(n)) return ic;
  }
  return "swap-bag";
}

export function svgIcon(name: string, color = "currentColor", size?: number): SVGSVGElement {
  const ns = "http://www.w3.org/2000/svg";
  const s = document.createElementNS(ns, "svg");
  s.setAttribute("viewBox", "0 0 512 512");
  s.setAttribute("aria-hidden", "true");
  if (size) {
    s.setAttribute("width", String(size));
    s.setAttribute("height", String(size));
  }
  const p = document.createElementNS(ns, "path");
  p.setAttribute("d", ICON[name] || ICON["swap-bag"]);
  p.setAttribute("fill", color);
  s.appendChild(p);
  return s;
}
